'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let pos = 0;
const N = input[pos++];
const M = input[pos++];

const turns = new Array(M);
for (let i = 0; i < M; i++) turns[i] = input[pos++];

const lengths = new Array(M + 1);
lengths[0] = N;

for (let i = 0; i < M; i++) {
  const t = turns[i];
  lengths[i + 1] = lengths[i] - Math.floor(lengths[i] / t);
}

const count = Math.min(10000, lengths[M]);
const guests = new Int32Array(count);

for (let i = 0; i < count; i++) guests[i] = i + 1;

for (let i = M - 1; i >= 0; i--) {
  const t = turns[i];
  const divisor = t - 1;
  for (let j = 0; j < count; j++) {
    const rank = guests[j];
    guests[j] = rank + Math.floor((rank - 1) / divisor);
  }
}

let output = '';
for (let i = 0; i < count; i++) output += guests[i] + '\n';
process.stdout.write(output);
